                    try {
                        const nativeFound = TvRemoteService.normalizeHostInput(w.SoarTvNative.discoverTv(lastKnownBaseUrl || ''));
                        if (nativeFound) {
                            return nativeFound;
                        }
                    }
                    catch {
                        // Fall through to JS subnet scan
                    }
