            const step = Math.max(4, batchSize);
            for (let i = 0; i < candidates.length; i += step) {
                const slice = candidates.slice(i, i + step);
                const found = await TvRemoteService.probeLanTv(slice, fetchImpl, probeTimeoutMs);
                if (found) {
                    return found;
                }
            }
            return null;
