        try {
            const updated = await remoteService.renamePairedDevice(deviceId, clean);
            lastAdminDevicesSig = '';
            renderPairedDevicesList(updated);
            showToast(`Renamed to ${clean}`);
        }
        catch (err) {
            showToast(err instanceof Error ? err.message : 'Failed to rename device');
        }
