    let latestAdminInvite = null;
    function sanitizeInlineQrSvg(rawSvg) {
        if (!rawSvg)
            return '';
        const trimmed = rawSvg.trim();
        if (!trimmed.startsWith('<svg ') || !trimmed.endsWith('</svg>'))
            return '';
        if (/script|onload|onerror|javascript:/i.test(trimmed))
            return '';
        return trimmed;
    }
